import type { OpenAPIV3 } from '@scalar/openapi-types'
import type { OAExampleObject, ParsedOperation, PlaygroundSecurityScheme } from '../../types'
import type { OARequest } from './request'
import { buildRequest } from './buildRequest'

/**
 * Builds the request used for an operation's code samples: first security
 * option, autogenerated body example and first request body content type.
 */
export function buildOperationRequest({
  path,
  method,
  operation,
  baseUrl,
  headers = {},
  parameters = operation.parameters || [],
}: {
  path: string
  method: string
  operation: ParsedOperation
  baseUrl: string
  headers?: Record<string, string>
  /** Defaults to the operation parameters. */
  parameters?: any[]
}): OARequest {
  const authorizations = operation.securityUi?.[0]?.schemes || {}

  // The body example must match the content type sent with it, so only the first one is used.
  const contentType = Object.keys(operation.requestBody?.content || {})[0]
  const examples: OAExampleObject[] = Object.values(
    (contentType && operation.requestBody?.content?.[contentType]?.examples) || {},
  )
  const autogeneratedRequestBodyExample = examples.find(example => example?.isAutogenerated)

  return buildRequest({
    path,
    method: method as OpenAPIV3.HttpMethods,
    baseUrl,
    parameters: parameters.filter((p): p is OpenAPIV3.ParameterObject => !('$ref' in p)),
    authorizations: Object.entries(authorizations).map(([name, value]: [string, any]) => {
      return {
        ...value,
        name: value.name ?? String(name),
        label: String(name),
      } as PlaygroundSecurityScheme
    }),
    body: autogeneratedRequestBodyExample?.value ?? undefined,
    headers: { ...headers },
    variables: {},
    contentType,
  })
}
